class Counter
    public define value as integer;
endClass

algorithm RunAlias
    define n as integer;
    define i as integer;
    define a as Counter;
    define b as Counter;
    read n;
    a <- new Counter();
    a.value <- 0;
    b <- a;
    for i <- 1 to n step 1 do
        b.value <- b.value + 1;
    endFor
    write a.value;
endAlgorithm
